import type { Dialogue, DialogueLine } from './dialogues';
import type { ListeningQuestion, ListeningStory } from './listeningStories';

type Level = 'A1' | 'A2' | 'B1' | 'B2' | 'C1';
type Pair = [english: string, spanish: string];
type TechnologyCase = {
  id: string;
  level: Level;
  title: string;
  titleEs: string;
  problem: Pair;
  check: Pair;
  reply: Pair;
  action: Pair;
  outcome: Pair;
};

// Ten listening cases per CEFR level; the language and technical work become
// more demanding at each level. Dialogue cases reuse these facts in role-play.
export const technologyCases: TechnologyCase[] = [
  // A1 · devices, accounts, and simple instructions
  { id:'a1-login', level:'A1', title:'Signing In at the Help Desk', titleEs:'Iniciar sesión en la mesa de ayuda', problem:['My account is locked. I cannot sign in.','Mi cuenta está bloqueada. No puedo iniciar sesión.'], check:['Do you see an error on the screen?','¿Ves un error en la pantalla?'], reply:['Yes. It says, “Try again later.”','Sí. Dice: «Inténtalo más tarde».'], action:['Open the official reset page. Do not share your password.','Abre la página oficial para restablecerla. No compartas tu contraseña.'], outcome:['I reset my password, and I can sign in now.','Restablecí mi contraseña y ya puedo iniciar sesión.'] },
  { id:'a1-wifi', level:'A1', title:'Connecting to Office Wi-Fi', titleEs:'Conectarse al wifi de la oficina', problem:['My laptop is not on the office Wi-Fi.','Mi laptop no está conectada al wifi de la oficina.'], check:['Is Wi-Fi on, and can you see the network name?','¿Está activado el wifi y ves el nombre de la red?'], reply:['Yes. I can see the name, but it says “No internet.”','Sí. Veo el nombre, pero dice «Sin internet».'], action:['Select the office network and ask the IT desk for the approved guest instructions.','Selecciona la red de la oficina y pide a TI las instrucciones autorizadas para invitados.'], outcome:['The laptop is connected, and the browser opens the intranet.','La laptop está conectada y el navegador abre la intranet.'] },
  { id:'a1-printer', level:'A1', title:'Printing a Class Schedule', titleEs:'Imprimir un horario de clase', problem:['The printer does not print my schedule.','La impresora no imprime mi horario.'], check:['Is there paper in the tray?','¿Hay papel en la bandeja?'], reply:['No. The paper tray is empty.','No. La bandeja está vacía.'], action:['Add paper, close the tray, and press Print again.','Pon papel, cierra la bandeja y vuelve a pulsar Imprimir.'], outcome:['The printer makes one copy of the schedule.','La impresora hace una copia del horario.'] },
  { id:'a1-headphones', level:'A1', title:'Finding the Headphone Output', titleEs:'Elegir la salida de los audífonos', problem:['I cannot hear the training video.','No puedo oír el video de capacitación.'], check:['Are the headphones connected to the computer?','¿Están conectados los audífonos a la computadora?'], reply:['Yes, but the sound is coming from the speakers.','Sí, pero el sonido sale por las bocinas.'], action:['Choose the headphones in the sound menu and raise the volume a little.','Selecciona los audífonos en el menú de sonido y sube un poco el volumen.'], outcome:['I can hear the video through my headphones.','Puedo oír el video por mis audífonos.'] },
  { id:'a1-keyboard', level:'A1', title:'Changing the Keyboard Language', titleEs:'Cambiar el idioma del teclado', problem:['My keyboard types the wrong symbols.','Mi teclado escribe símbolos equivocados.'], check:['Does the language icon show English or Spanish?','¿El icono de idioma muestra inglés o español?'], reply:['It shows Spanish, but I need English.','Muestra español, pero necesito inglés.'], action:['Choose English in the language menu and test one key.','Elige inglés en el menú de idioma y prueba una tecla.'], outcome:['The symbols match the English keyboard now.','Ahora los símbolos coinciden con el teclado en inglés.'] },
  { id:'a1-battery', level:'A1', title:'Charging a Laptop', titleEs:'Cargar una laptop', problem:['My laptop battery is almost empty.','La batería de mi laptop está casi vacía.'], check:['Is the charger connected to the laptop and the wall?','¿El cargador está conectado a la laptop y al enchufe?'], reply:['It is connected to the laptop, but not to the wall.','Está conectado a la laptop, pero no al enchufe.'], action:['Connect the charger to a safe power outlet and check the light.','Conecta el cargador a un enchufe seguro y revisa la luz.'], outcome:['The charging light is on, and the battery is charging.','La luz de carga está encendida y la batería se está cargando.'] },
  { id:'a1-file', level:'A1', title:'Finding a Saved File', titleEs:'Encontrar un archivo guardado', problem:['I cannot find my English homework file.','No encuentro mi archivo de tarea de inglés.'], check:['Did you save it in Documents or Downloads?','¿Lo guardaste en Documentos o Descargas?'], reply:['I saved it in Downloads this morning.','Lo guardé en Descargas esta mañana.'], action:['Open Downloads and search for the file name.','Abre Descargas y busca el nombre del archivo.'], outcome:['I found the document and opened it.','Encontré el documento y lo abrí.'] },
  { id:'a1-brightness', level:'A1', title:'Making the Screen Brighter', titleEs:'Aumentar el brillo de la pantalla', problem:['The screen is too dark for my lesson.','La pantalla está demasiado oscura para mi clase.'], check:['Can you see the brightness control?','¿Puedes ver el control de brillo?'], reply:['Yes. The brightness is set very low.','Sí. El brillo está muy bajo.'], action:['Move the brightness control up a little.','Sube un poco el control de brillo.'], outcome:['I can read the lesson on the screen now.','Ahora puedo leer la lección en la pantalla.'] },
  { id:'a1-mouse', level:'A1', title:'Connecting a Wireless Mouse', titleEs:'Conectar un ratón inalámbrico', problem:['My mouse does not move the pointer.','Mi ratón no mueve el puntero.'], check:['Is the mouse switched on?','¿Está encendido el ratón?'], reply:['No. The small switch is off.','No. El interruptor pequeño está apagado.'], action:['Turn it on and wait for the light.','Enciéndelo y espera a que aparezca la luz.'], outcome:['The pointer moves when I move the mouse.','El puntero se mueve cuando muevo el ratón.'] },
  { id:'a1-webcam', level:'A1', title:'Turning On the Webcam', titleEs:'Activar la cámara web', problem:['The class cannot see me in the video call.','La clase no puede verme en la videollamada.'], check:['Is the camera cover open?','¿Está abierta la cubierta de la cámara?'], reply:['No. I closed the small cover.','No. Cerré la cubierta pequeña.'], action:['Open the cover and select the camera in the call.','Abre la cubierta y selecciona la cámara en la llamada.'], outcome:['My face appears in the video window.','Mi cara aparece en la ventana de video.'] },

  // A2 · describe symptoms, report what happened, follow safe steps
  { id:'a2-slow-app', level:'A2', title:'A Slow Design Application', titleEs:'Una aplicación de diseño lenta', problem:['Yesterday the design application became very slow.','Ayer la aplicación de diseño se volvió muy lenta.'], check:['Did it start after you opened several large files?','¿Empezó después de abrir varios archivos grandes?'], reply:['Yes. I opened three projects at the same time.','Sí. Abrí tres proyectos al mismo tiempo.'], action:['Save your work, close the files you do not need, and restart the application.','Guarda tu trabajo, cierra los archivos que no necesitas y reinicia la aplicación.'], outcome:['The application opened one project smoothly.','La aplicación abrió un proyecto sin problemas.'] },
  { id:'a2-update', level:'A2', title:'Retrying a Software Update', titleEs:'Reintentar una actualización de software', problem:['The update stopped at twenty percent last night.','La actualización se detuvo en veinte por ciento anoche.'], check:['Was the laptop connected to power and the internet?','¿La laptop estaba conectada a la corriente y a internet?'], reply:['It was on battery, and the Wi-Fi disconnected.','Estaba usando la batería y se desconectó el wifi.'], action:['Connect to power and stable Wi-Fi, then restart the approved update.','Conéctala a la corriente y a un wifi estable; después reinicia la actualización autorizada.'], outcome:['The update finished, and the version number changed.','La actualización terminó y cambió el número de versión.'] },
  { id:'a2-attachment', level:'A2', title:'Opening a Safe Email Attachment', titleEs:'Abrir un archivo adjunto seguro', problem:['I could not open the project attachment this morning.','No pude abrir el archivo adjunto del proyecto esta mañana.'], check:['Did it come from someone you know, and what file type is it?','¿Lo envió alguien que conoces y qué tipo de archivo es?'], reply:['It came from my instructor, and it is a PDF.','Lo envió mi instructor y es un PDF.'], action:['Confirm the message is expected, then open the PDF with the approved reader.','Confirma que esperabas el mensaje y abre el PDF con el lector autorizado.'], outcome:['I read the project notes without enabling extra content.','Leí las notas del proyecto sin habilitar contenido adicional.'] },
  { id:'a2-video-call', level:'A2', title:'Joining a Video Meeting', titleEs:'Entrar a una reunión por video', problem:['My camera and microphone did not work in the meeting.','Mi cámara y micrófono no funcionaron en la reunión.'], check:['Did the browser ask for permission, and did you select the devices?','¿El navegador pidió permiso y seleccionaste los dispositivos?'], reply:['I selected the wrong microphone and blocked the camera.','Elegí el micrófono equivocado y bloqueé la cámara.'], action:['Choose the correct devices and allow access for this trusted meeting site.','Elige los dispositivos correctos y permite el acceso a este sitio de reunión confiable.'], outcome:['The test shows a clear picture and sound.','La prueba muestra imagen y sonido claros.'] },
  { id:'a2-cloud-sync', level:'A2', title:'Resuming Cloud File Sync', titleEs:'Reanudar la sincronización en la nube', problem:['My class files did not sync yesterday.','Mis archivos de clase no se sincronizaron ayer.'], check:['Was the sync app signed in and online?','¿La aplicación de sincronización tenía sesión iniciada y conexión?'], reply:['It was signed out after I changed computers.','La sesión se cerró después de que cambié de computadora.'], action:['Sign in through the official app and check the sync status.','Inicia sesión desde la aplicación oficial y revisa el estado de sincronización.'], outcome:['The status changed to “Up to date.”','El estado cambió a «Actualizado».'] },
  { id:'a2-browser-cache', level:'A2', title:'A Website That Will Not Load', titleEs:'Un sitio web que no carga', problem:['The course website did not load in my browser.','El sitio del curso no cargó en mi navegador.'], check:['Did another trusted website open on the same connection?','¿Abrió otro sitio confiable con la misma conexión?'], reply:['Yes. Only the course page showed an error.','Sí. Solo la página del curso mostró un error.'], action:['Refresh the page, then clear only the site cache if the error continues.','Actualiza la página y, si continúa el error, borra solo la caché de ese sitio.'], outcome:['The course page loaded without removing my saved passwords.','La página del curso cargó sin borrar mis contraseñas guardadas.'] },
  { id:'a2-scanner', level:'A2', title:'Reconnecting a Document Scanner', titleEs:'Reconectar un escáner de documentos', problem:['The scanner stopped appearing on my computer.','El escáner dejó de aparecer en mi computadora.'], check:['Did you connect it to a different USB port?','¿Lo conectaste a otro puerto USB?'], reply:['Yes. The cable was loose in the first port.','Sí. El cable estaba flojo en el primer puerto.'], action:['Reconnect the cable firmly and open the approved scanning application.','Conecta bien el cable y abre la aplicación de escaneo autorizada.'], outcome:['The scanner appeared, and the test page was clear.','Apareció el escáner y la página de prueba salió nítida.'] },
  { id:'a2-password-reset', level:'A2', title:'Resetting a Forgotten Password', titleEs:'Restablecer una contraseña olvidada', problem:['I forgot the password for my training account.','Olvidé la contraseña de mi cuenta de capacitación.'], check:['Can you reach the organization’s official sign-in page?','¿Puedes entrar a la página oficial de inicio de sesión de la organización?'], reply:['Yes. I can see the reset option below the sign-in form.','Sí. Veo la opción de restablecimiento debajo del formulario.'], action:['Use the reset option and verify your identity there; never send a code to support.','Usa esa opción y verifica tu identidad ahí; nunca envíes un código a soporte.'], outcome:['I created a new password on the official page and signed in.','Creé una contraseña nueva en la página oficial e inicié sesión.'] },
  { id:'a2-storage', level:'A2', title:'Making Space for a Class Project', titleEs:'Liberar espacio para un proyecto escolar', problem:['My tablet said there was not enough space for the project.','Mi tableta indicó que no había espacio suficiente para el proyecto.'], check:['Which files use the most space, and are they backed up?','¿Qué archivos ocupan más espacio y tienen copia de seguridad?'], reply:['Old videos use most of it, and I saved them to the school drive.','Los videos antiguos ocupan casi todo y los guardé en la unidad escolar.'], action:['Review the backup first, then remove only duplicate files you recognize.','Primero revisa la copia; después elimina solo los duplicados que reconozcas.'], outcome:['The tablet has space for the project, and the originals remain backed up.','La tableta tiene espacio para el proyecto y los originales siguen respaldados.'] },
  { id:'a2-projector', level:'A2', title:'Getting the Projector Signal Back', titleEs:'Recuperar la señal del proyector', problem:['The classroom projector showed “No signal” before the presentation.','El proyector del aula mostró «Sin señal» antes de la presentación.'], check:['Did you select the input that matches the laptop cable?','¿Seleccionaste la entrada que corresponde al cable de la laptop?'], reply:['No. The projector was set to HDMI two, but the cable was in HDMI one.','No. El proyector estaba en HDMI dos, pero el cable estaba en HDMI uno.'], action:['Select HDMI one and duplicate the laptop display.','Selecciona HDMI uno y duplica la pantalla de la laptop.'], outcome:['The presentation appeared on the screen.','La presentación apareció en la pantalla.'] },

  // B1 · network diagnostics, source control, logs, and escalation
  { id:'b1-vpn', level:'B1', title:'Diagnosing a VPN Connection', titleEs:'Diagnosticar una conexión VPN', problem:['I have been unable to reach the internal tools since the VPN disconnected.','No he podido acceder a las herramientas internas desde que se desconectó la VPN.'], check:['Can you reach a public site, and does the VPN client show a specific error?','¿Puedes abrir un sitio público y el cliente VPN muestra un error específico?'], reply:['Public sites work, but the client reports a gateway timeout.','Los sitios públicos funcionan, pero el cliente informa un tiempo de espera de la puerta de enlace.'], action:['Record the time and error, reconnect once using the approved profile, and escalate if it persists.','Registra la hora y el error, vuelve a conectar una vez con el perfil autorizado y escala el caso si continúa.'], outcome:['The second attempt connected; support kept the error details for monitoring.','El segundo intento se conectó; soporte conservó los detalles del error para monitorear.'] },
  { id:'b1-dns', level:'B1', title:'Finding a DNS Resolution Problem', titleEs:'Detectar un problema de resolución DNS', problem:['Several staff members can open IP-based services but not the intranet name.','Varias personas pueden abrir servicios por IP, pero no por el nombre de la intranet.'], check:['Does the DNS lookup return the expected internal address?','¿La consulta DNS devuelve la dirección interna esperada?'], reply:['No. It returns no record from the office network.','No. No devuelve ningún registro desde la red de la oficina.'], action:['Compare the resolver response with a known-good device and send the timestamp to network support.','Compara la respuesta del resolvedor con un dispositivo que funciona y envía la hora a soporte de red.'], outcome:['The resolver configuration was corrected, and the intranet name resolved.','Se corrigió la configuración del resolvedor y el nombre de la intranet se resolvió.'] },
  { id:'b1-latency', level:'B1', title:'Investigating Network Latency', titleEs:'Investigar latencia de red', problem:['Video calls have been lagging in the east office since Monday.','Las videollamadas presentan retraso en la oficina este desde el lunes.'], check:['Do wired devices show the same delay, and when does packet loss increase?','¿Los equipos cableados muestran el mismo retraso y cuándo aumenta la pérdida de paquetes?'], reply:['Yes. The loss rises during the afternoon across two meeting rooms.','Sí. La pérdida aumenta por la tarde en dos salas de reunión.'], action:['Capture approved network metrics and compare peak hours with the switch-port counters.','Recopila métricas de red autorizadas y compara las horas pico con los contadores del puerto del conmutador.'], outcome:['The evidence pointed to a congested uplink, so the network team scheduled a capacity change.','La evidencia señaló un enlace ascendente congestionado, así que redes programó ampliar la capacidad.'] },
  { id:'b1-git-conflict', level:'B1', title:'Resolving a Git Merge Conflict', titleEs:'Resolver un conflicto de combinación en Git', problem:['My feature branch conflicts with the current configuration file.','Mi rama de funcionalidad entra en conflicto con el archivo de configuración actual.'], check:['Have you inspected both changes before choosing which lines to keep?','¿Revisaste ambos cambios antes de decidir qué líneas conservar?'], reply:['Yes. One change adds a timeout, and the other updates the endpoint.','Sí. Un cambio agrega un tiempo de espera y el otro actualiza el endpoint.'], action:['Discuss the intended behavior with the owners, resolve the file, and run the relevant tests.','Acuerda el comportamiento previsto con sus responsables, resuelve el archivo y ejecuta las pruebas pertinentes.'], outcome:['The merge passed the tests, and the branch was ready for review.','La combinación pasó las pruebas y la rama quedó lista para revisión.'] },
  { id:'b1-database', level:'B1', title:'Tracing a Database Timeout', titleEs:'Rastrear un tiempo de espera de base de datos', problem:['The reporting service has timed out when it queries the database.','El servicio de informes agotó el tiempo de espera al consultar la base de datos.'], check:['Do the logs show a slow query, a connection limit, or a network failure?','¿Los registros muestran una consulta lenta, un límite de conexiones o una falla de red?'], reply:['They show that the connection pool reached its limit during the nightly job.','Muestran que el conjunto de conexiones llegó a su límite durante el proceso nocturno.'], action:['Correlate the job time with query duration and escalate the metrics without copying customer data.','Relaciona la hora del proceso con la duración de las consultas y escala las métricas sin copiar datos de clientes.'], outcome:['The team adjusted the pool after testing the change outside production.','El equipo ajustó el conjunto después de probar el cambio fuera de producción.'] },
  { id:'b1-api', level:'B1', title:'Investigating an API Error', titleEs:'Investigar un error de API', problem:['The inventory API has returned a 500 error for several requests.','La API de inventario ha devuelto un error 500 en varias solicitudes.'], check:['Do the request IDs point to the same service and deployment?','¿Los identificadores de solicitud apuntan al mismo servicio y despliegue?'], reply:['Yes. The failures began after the latest service deployment.','Sí. Las fallas comenzaron después del último despliegue del servicio.'], action:['Compare the deployment logs, roll back only if the approved criteria are met, and notify the owner.','Compara los registros del despliegue, revierte solo si se cumplen los criterios aprobados y avisa al responsable.'], outcome:['The team isolated a configuration change and restored the previous stable version.','El equipo aisló un cambio de configuración y restauró la versión estable anterior.'] },
  { id:'b1-linux-permissions', level:'B1', title:'Correcting Linux File Permissions', titleEs:'Corregir permisos de archivos en Linux', problem:['A scheduled script cannot read its configuration file on Linux.','Un script programado no puede leer su archivo de configuración en Linux.'], check:['Which user runs the process, and what permissions does the file have?','¿Qué usuario ejecuta el proceso y qué permisos tiene el archivo?'], reply:['The service user lacks read access, while the file belongs to the deployment account.','Al usuario del servicio le falta permiso de lectura y el archivo pertenece a la cuenta de despliegue.'], action:['Grant the service account only the required read permission and verify ownership.','Concede a la cuenta del servicio solo el permiso de lectura necesario y verifica la propiedad.'], outcome:['The script read the file without granting broader access.','El script leyó el archivo sin conceder acceso más amplio.'] },
  { id:'b1-cloud-role', level:'B1', title:'Restoring Cloud Storage Access', titleEs:'Restablecer acceso al almacenamiento en la nube', problem:['A project team lost access to one shared cloud folder.','Un equipo de proyecto perdió acceso a una carpeta compartida en la nube.'], check:['Was the team role changed, or did the sharing link expire?','¿Cambió el rol del equipo o expiró el vínculo compartido?'], reply:['The link expired after the project owner updated the folder policy.','El vínculo expiró después de que el responsable actualizó la política de la carpeta.'], action:['Ask the owner to grant the group the minimum required role through the console.','Pide al responsable que asigne al grupo el rol mínimo necesario desde la consola.'], outcome:['The team regained access, and the public link remained disabled.','El equipo recuperó el acceso y el vínculo público siguió desactivado.'] },

  // B2 · security, controlled change, recovery, and service management
  { id:'b2-suspicious-login', level:'B2', title:'Responding to an Unfamiliar Sign-In', titleEs:'Responder a un inicio de sesión desconocido', problem:['An employee reported an unfamiliar sign-in alert on a corporate account.','Un empleado reportó una alerta de inicio de sesión desconocido en una cuenta corporativa.'], check:['Has the user confirmed the alert through the official security portal?','¿El usuario confirmó la alerta desde el portal oficial de seguridad?'], reply:['Yes. The time and device do not match the employee’s activity.','Sí. La hora y el dispositivo no coinciden con la actividad del empleado.'], action:['Revoke active sessions, require the approved recovery flow, and notify the security team.','Revoca las sesiones activas, exige el proceso autorizado de recuperación y avisa al equipo de seguridad.'], outcome:['Access was contained, and the incident record contains verified events only.','Se contuvo el acceso y el registro del incidente contiene solo eventos verificados.'] },
  { id:'b2-phishing', level:'B2', title:'Handling a Suspected Phishing Message', titleEs:'Atender un posible mensaje de phishing', problem:['Several employees received a message that imitates the company sign-in page.','Varios empleados recibieron un mensaje que imita la página de inicio de sesión de la empresa.'], check:['Did anyone submit credentials, and has the message been reported with its headers?','¿Alguien ingresó credenciales y se reportó el mensaje con sus encabezados?'], reply:['Two people reported it; neither entered a password, and the headers are preserved.','Dos personas lo reportaron; ninguna ingresó una contraseña y se conservaron los encabezados.'], action:['Quarantine the message, block its verified indicators, and send a concise warning through the internal channel.','Pon el mensaje en cuarentena, bloquea sus indicadores verificados y envía una alerta breve por el canal interno.'], outcome:['The campaign was contained before confirmed account access occurred.','La campaña se contuvo antes de que ocurriera un acceso confirmado a las cuentas.'] },
  { id:'b2-patch-rollout', level:'B2', title:'Planning a Production Patch', titleEs:'Planificar un parche de producción', problem:['A critical patch is ready, but the service cannot tolerate an unplanned outage.','Hay un parche crítico listo, pero el servicio no puede tolerar una interrupción no planificada.'], check:['Has the patch passed staging tests, and is rollback automation available?','¿El parche pasó las pruebas de preparación y existe una reversión automatizada?'], reply:['Staging passed, and rollback is available, but one integration remains untested.','Preparación pasó y la reversión está disponible, pero falta probar una integración.'], action:['Deploy to a small canary group, monitor the agreed indicators, and pause if the error budget is exceeded.','Despliega a un grupo canario pequeño, monitorea los indicadores acordados y pausa si se excede el presupuesto de errores.'], outcome:['The canary stayed healthy, so the team expanded the rollout in controlled stages.','El canario se mantuvo estable, así que el equipo amplió el despliegue por etapas controladas.'] },
  { id:'b2-backup', level:'B2', title:'Restoring from an Immutable Backup', titleEs:'Restaurar desde una copia inmutable', problem:['A file server may have been encrypted, and the team is considering recovery.','Un servidor de archivos podría haberse cifrado y el equipo considera recuperarlo.'], check:['Has the incident been contained, and was the backup isolated from the affected credentials?','¿Se contuvo el incidente y la copia quedó aislada de las credenciales afectadas?'], reply:['The affected host is isolated, and the backup vault uses separate access controls.','El equipo afectado está aislado y la bóveda usa controles de acceso independientes.'], action:['Validate the recovery point in an isolated environment before restoring business data.','Valida el punto de recuperación en un entorno aislado antes de restaurar datos de negocio.'], outcome:['The test restore was clean, and the recovery lead approved the next step.','La restauración de prueba estaba limpia y el responsable de recuperación aprobó el siguiente paso.'] },
  { id:'b2-data-exposure', level:'B2', title:'Investigating Possible Data Exposure', titleEs:'Investigar una posible exposición de datos', problem:['An access log suggests that a shared report may have been visible outside its team.','Un registro sugiere que un informe compartido pudo quedar visible fuera de su equipo.'], check:['Can the team verify the scope, time window, and data classification without copying records?','¿Puede el equipo verificar el alcance, el periodo y la clasificación sin copiar registros?'], reply:['The link was public for twelve minutes, but access logs show no confirmed download.','El vínculo fue público durante doce minutos, pero los registros no muestran descargas confirmadas.'], action:['Disable the link, preserve the audit trail, and follow the organization’s incident notification process.','Desactiva el vínculo, conserva la auditoría y sigue el proceso de notificación de incidentes de la organización.'], outcome:['The exposure was contained, and the privacy team received a factual timeline.','Se contuvo la exposición y el equipo de privacidad recibió una cronología basada en hechos.'] },
  { id:'b2-iam-review', level:'B2', title:'Reviewing Cloud Access Permissions', titleEs:'Revisar permisos de acceso a la nube', problem:['A review found that a contractor role can modify more cloud resources than required.','Una revisión detectó que el rol de un contratista puede modificar más recursos de nube de los necesarios.'], check:['Which actions are essential for the contract, and who approves the role?','¿Qué acciones son esenciales para el contrato y quién aprueba el rol?'], reply:['The contractor needs read access to one project; the service owner approves it.','El contratista necesita lectura en un proyecto y lo aprueba el responsable del servicio.'], action:['Replace the broad policy with a scoped read-only role and record the expiry date.','Sustituye la política amplia por un rol de solo lectura limitado y registra su vencimiento.'], outcome:['The access review confirmed the reduced permissions and a scheduled expiry.','La revisión confirmó los permisos reducidos y un vencimiento programado.'] },
  { id:'b2-sla', level:'B2', title:'Explaining an SLA Service Interruption', titleEs:'Explicar una interrupción según el SLA', problem:['A customer service missed its availability target during a regional outage.','Un servicio al cliente no alcanzó su objetivo de disponibilidad durante una interrupción regional.'], check:['Do monitoring data and the contract define the same measurement window?','¿Los datos de monitoreo y el contrato definen el mismo periodo de medición?'], reply:['They do, and the incident timeline shows a forty-minute impact.','Sí, y la cronología muestra un impacto de cuarenta minutos.'], action:['Share the verified timeline, explain the mitigation, and calculate any credit under the contract.','Comparte la cronología verificada, explica la mitigación y calcula el crédito que corresponda al contrato.'], outcome:['The customer received a clear report and the applicable service credit.','El cliente recibió un informe claro y el crédito de servicio correspondiente.'] },
  { id:'b2-release', level:'B2', title:'Coordinating a Database Release', titleEs:'Coordinar una publicación de base de datos', problem:['The release changes a database schema used by two services.','La publicación cambia un esquema de base de datos usado por dos servicios.'], check:['Are backward-compatible reads tested, and can the migration be reversed safely?','¿Se probaron las lecturas retrocompatibles y puede revertirse la migración sin riesgo?'], reply:['Reads passed, but the rollback script needs a review from the data owner.','Las lecturas pasaron, pero el responsable de datos debe revisar el script de reversión.'], action:['Delay the production window until the owner signs off and the recovery rehearsal passes.','Retrasa la ventana de producción hasta obtener la aprobación y completar el ensayo de recuperación.'], outcome:['The release proceeded with an approved rollback plan and no data loss.','La publicación avanzó con un plan de reversión aprobado y sin pérdida de datos.'] },
  { id:'b2-retention', level:'B2', title:'Applying a Data Retention Policy', titleEs:'Aplicar una política de retención de datos', problem:['A shared workspace contains logs older than the approved retention period.','Un espacio compartido contiene registros anteriores al periodo de retención aprobado.'], check:['Are any records under a legal hold or required for an active investigation?','¿Hay registros sujetos a conservación legal o necesarios para una investigación activa?'], reply:['The owner confirmed one investigation set must remain; the rest can be reviewed.','El responsable confirmó que debe conservarse un conjunto de investigación; el resto puede revisarse.'], action:['Preserve the exception, then remove eligible logs through the approved retention workflow.','Conserva la excepción y elimina los registros elegibles con el flujo de retención aprobado.'], outcome:['The workspace meets policy, and the exception is documented for review.','El espacio cumple la política y la excepción quedó documentada para revisión.'] },
  { id:'b2-monitoring', level:'B2', title:'Reducing Noisy Monitoring Alerts', titleEs:'Reducir alertas ruidosas de monitoreo', problem:['The on-call team receives repeated alerts that do not affect users.','El equipo de guardia recibe alertas repetidas que no afectan a los usuarios.'], check:['Does each alert map to a user impact or an actionable service threshold?','¿Cada alerta corresponde a un impacto en usuarios o a un umbral accionable?'], reply:['Several alerts track a low-level metric with no linked service symptom.','Varias alertas siguen una métrica menor sin un síntoma de servicio asociado.'], action:['Tune the threshold in staging, preserve the paging rule for real impact, and review after one week.','Ajusta el umbral en preparación, conserva la alerta crítica para impactos reales y revisa en una semana.'], outcome:['The team reduced noise without hiding the service-level alerts.','El equipo redujo el ruido sin ocultar las alertas de nivel de servicio.'] },

  // C1 · architecture, resilience, governance, and executive communication
  { id:'b1-cloud-outage', level:'B1', title:'Reporting a Cloud Service Outage', titleEs:'Reportar una interrupción de nube', problem:['The cloud service is offline, and users cannot open the company app.','El servicio de nube está desconectado y los usuarios no pueden abrir la aplicación de la empresa.'], check:['Which teams are affected, and when did the problem start?','¿Qué equipos están afectados y cuándo comenzó el problema?'], reply:['It began after a regional network issue; email still works.','Comenzó después de un problema de red regional; el correo todavía funciona.'], action:['Check the provider status, follow the recovery steps, and update users every thirty minutes.','Revisa el estado del proveedor, sigue los pasos de recuperación e informa a los usuarios cada treinta minutos.'], outcome:['The service is back online, and the team has sent a status update.','El servicio volvió a estar disponible y el equipo envió una actualización.'] },
  { id:'b1-cloud-capacity', level:'B1', title:'Reviewing Cloud Capacity', titleEs:'Revisar la capacidad de nube', problem:['The new release uses too much cloud capacity.','La nueva versión usa demasiada capacidad de nube.'], check:['When did the cost increase, and which service uses the most resources?','¿Cuándo aumentó el costo y qué servicio usa más recursos?'], reply:['The increase began after yesterday’s release, especially during busy hours.','El aumento comenzó después de la publicación de ayer, sobre todo en horas de mayor actividad.'], action:['Review the usage chart, test a smaller setting, and keep the rollback plan ready.','Revisa el gráfico de uso, prueba una configuración menor y ten listo el plan de reversión.'], outcome:['The service meets its response target with less unused capacity.','El servicio cumple su objetivo de respuesta con menos capacidad sin usar.'] },
  { id:'c1-root-cause', level:'C1', title:'Tracing Connection Pool Exhaustion', titleEs:'Rastrear el agotamiento del conjunto de conexiones', problem:['A production API slowed after a release, although CPU and memory remained within normal ranges.','Una API de producción se ralentizó tras una publicación, aunque CPU y memoria seguían normales.'], check:['Do traces show requests waiting for database connections, and does the timing match the release?','¿Las trazas muestran solicitudes esperando conexiones de base de datos y coincide la hora con la publicación?'], reply:['Yes. The new retry path holds connections longer during transient failures.','Sí. La nueva ruta de reintentos retiene conexiones más tiempo durante fallas transitorias.'], action:['Limit retries with backoff, restore the previous pool behavior, and verify the change under representative load.','Limita los reintentos con espera progresiva, restaura el comportamiento previo del conjunto y valida con carga representativa.'], outcome:['Latency returned to target; the post-incident review assigned ownership for retry-budget design.','La latencia volvió al objetivo; la revisión asignó responsables para diseñar el presupuesto de reintentos.'] },
  { id:'c1-migration', level:'C1', title:'Sequencing a Legacy Database Migration', titleEs:'Secuenciar la migración de una base heredada', problem:['A legacy database must move to a managed cloud service without interrupting the reporting pipeline.','Una base de datos heredada debe migrarse a un servicio de nube administrado sin interrumpir informes.'], check:['Can both systems remain consistent during replication, and has rollback been rehearsed?','¿Pueden ambos sistemas mantener consistencia durante la replicación y se ensayó la reversión?'], reply:['Replication is viable, but one downstream consumer assumes the old timestamp format.','La replicación es viable, pero un consumidor posterior supone el formato de hora antiguo.'], action:['Version the interface, migrate a representative dataset, and gate cutover on reconciliation evidence.','Versiona la interfaz, migra un conjunto representativo y condiciona el cambio a evidencia de conciliación.'], outcome:['The phased migration completed without losing reports, and the consumer now supports both formats.','La migración por fases terminó sin perder informes y el consumidor ya admite ambos formatos.'] },
  { id:'c1-zero-trust', level:'C1', title:'Introducing Zero-Trust Access', titleEs:'Introducir acceso de confianza cero', problem:['A network redesign must reduce implicit trust without blocking essential operations.','Un rediseño de red debe reducir la confianza implícita sin bloquear operaciones esenciales.'], check:['Which identities, devices, and service paths are evidenced well enough to define policy?','¿Qué identidades, dispositivos y rutas de servicio cuentan con evidencia suficiente para definir políticas?'], reply:['The inventory is incomplete for two legacy systems, though access logs reveal their dependencies.','El inventario está incompleto en dos sistemas heredados, aunque los registros muestran dependencias.'], action:['Map those flows, pilot identity-aware controls with a rollback path, and measure denied legitimate requests.','Mapea esos flujos, prueba controles basados en identidad con reversión y mide rechazos legítimos.'], outcome:['The pilot narrowed access without disrupting the documented service paths.','La prueba redujo el acceso sin interrumpir las rutas documentadas.'] },
  { id:'c1-disaster-recovery', level:'C1', title:'Revalidating Disaster-Recovery Targets', titleEs:'Revalidar objetivos de recuperación ante desastres', problem:['A recovery exercise met the documented RTO but exceeded the business unit’s acceptable data loss.','Un ejercicio cumplió el RTO documentado, pero superó la pérdida de datos aceptable para el área.'], check:['Do the RPO, backup cadence, and business impact analysis still reflect current dependencies?','¿El RPO, la frecuencia de copias y el análisis de impacto reflejan las dependencias actuales?'], reply:['The reporting dependency changed, but its recovery objective was never revised.','La dependencia de informes cambió, pero nunca se revisó su objetivo de recuperación.'], action:['Reassess service tiers with owners, fund the required replication, and repeat a timed recovery exercise.','Reevalúa los niveles con sus responsables, financia la replicación necesaria y repite el ejercicio cronometrado.'], outcome:['The revised plan met the agreed recovery window and documented its remaining constraints.','El plan revisado cumplió la ventana acordada y documentó las limitaciones restantes.'] },
  { id:'c1-observability', level:'C1', title:'Improving Signal Quality for SLOs', titleEs:'Mejorar señales para los SLO', problem:['The service reports healthy dashboards while users continue to experience intermittent failures.','El servicio muestra paneles saludables mientras algunos usuarios sufren fallas intermitentes.'], check:['Do the indicators measure successful user journeys across regions, or only component uptime?','¿Los indicadores miden recorridos exitosos de usuarios entre regiones o solo disponibilidad de componentes?'], reply:['They measure component uptime; failed transactions are excluded from the current SLO.','Miden disponibilidad de componentes; las transacciones fallidas no cuentan en el SLO actual.'], action:['Define a user-centered indicator, validate its data quality, and set an error-budget policy with product owners.','Define un indicador centrado en usuarios, valida los datos y acuerda un presupuesto de errores con producto.'], outcome:['The revised SLO exposed the failures and gave teams a shared basis for prioritization.','El SLO revisado hizo visibles las fallas y dio a los equipos una base común para priorizar.'] },
  { id:'c1-data-governance', level:'C1', title:'Governing Sensitive Telemetry', titleEs:'Gobernar telemetría sensible', problem:['A diagnostics proposal would retain detailed user telemetry longer than the stated support need.','Una propuesta de diagnóstico conservaría telemetría detallada más tiempo del necesario para soporte.'], check:['Which fields are necessary, who can access them, and when must each field expire?','¿Qué campos son necesarios, quién puede acceder y cuándo vence cada campo?'], reply:['Device error codes are useful; precise location and personal content are not required.','Los códigos de error del dispositivo son útiles; no hace falta ubicación precisa ni contenido personal.'], action:['Minimize collection, separate identifiers, enforce a short retention window, and audit access.','Minimiza la recopilación, separa identificadores, aplica retención breve y audita el acceso.'], outcome:['Support retained actionable diagnostics while reducing exposure and deletion risk.','Soporte conservó diagnósticos útiles y redujo riesgos de exposición y eliminación.'] },
  { id:'c1-technical-debt', level:'C1', title:'Prioritizing Technical Debt', titleEs:'Priorizar deuda técnica', problem:['A tightly coupled deployment process makes small changes risky and slows incident fixes.','Un proceso de despliegue muy acoplado vuelve riesgosos los cambios pequeños y retrasa correcciones.'], check:['Which failure modes create measurable operational cost, and what dependency should be decoupled first?','¿Qué fallas generan costos operativos medibles y qué dependencia conviene desacoplar primero?'], reply:['Shared configuration causes most rollbacks; the payment service is the highest-impact dependency.','La configuración compartida causa la mayoría de las reversiones; pagos es la dependencia más crítica.'], action:['Isolate configuration behind a versioned interface and validate the migration with staged releases.','Aísla la configuración tras una interfaz versionada y valida la migración con publicaciones graduales.'], outcome:['Rollback frequency declined, and the team could deploy a fix without coordinating every service.','Disminuyeron las reversiones y el equipo pudo corregir sin coordinar todos los servicios.'] },
  { id:'c1-incident-leadership', level:'C1', title:'Leading a Cross-Team Incident Review', titleEs:'Liderar una revisión de incidente entre equipos', problem:['A service interruption crossed infrastructure, application, and vendor boundaries.','Una interrupción atravesó infraestructura, aplicación y límites del proveedor.'], check:['Which facts are confirmed, who owns each mitigation, and when will the next update be issued?','¿Qué hechos están confirmados, quién es responsable de cada mitigación y cuándo será la siguiente actualización?'], reply:['The trigger is known, but the vendor’s contribution remains under investigation.','Se conoce el desencadenante, pero la contribución del proveedor sigue bajo investigación.'], action:['Separate facts from hypotheses, assign time-bound actions, and communicate customer impact without speculation.','Separa hechos de hipótesis, asigna acciones con plazo y comunica el impacto sin especular.'], outcome:['The review produced accountable follow-ups and a customer update grounded in verified evidence.','La revisión generó acciones responsables y una actualización al cliente basada en evidencia verificada.'] },
  { id:'c1-supply-chain', level:'C1', title:'Assessing a Software Supply-Chain Alert', titleEs:'Evaluar una alerta de cadena de suministro de software', problem:['A dependency advisory affects a library used in several production services.','Un aviso sobre dependencias afecta una biblioteca usada en varios servicios de producción.'], check:['Which deployed versions include the vulnerable path, and is exploitation confirmed?','¿Qué versiones desplegadas incluyen la ruta vulnerable y se confirmó explotación?'], reply:['Three services include it; no exploitation is confirmed, but one endpoint is internet-facing.','Tres servicios la incluyen; no hay explotación confirmada, pero un endpoint está expuesto a internet.'], action:['Prioritize the exposed service, pin a verified patched release, and monitor for indicators while teams update.','Prioriza el servicio expuesto, fija una versión corregida verificada y monitorea indicadores durante la actualización.'], outcome:['The highest-risk path was mitigated first, and the inventory now supports follow-up checks.','Se mitigó primero la ruta de mayor riesgo y el inventario permite revisiones posteriores.'] },
  { id:'c1-ai-governance', level:'C1', title:'Governing an AI Coding Assistant', titleEs:'Gobernar un asistente de programación con IA', problem:['A coding assistant improves drafting speed, yet may expose proprietary context or produce insecure suggestions.','Un asistente acelera borradores, pero podría exponer contexto propietario o sugerir código inseguro.'], check:['What data leaves the environment, how are suggestions reviewed, and which use cases are prohibited?','¿Qué datos salen del entorno, cómo se revisan las sugerencias y qué usos se prohíben?'], reply:['The current pilot logs prompts externally, and reviewers do not consistently check dependency changes.','La prueba registra instrucciones externamente y las revisiones no siempre verifican cambios de dependencias.'], action:['Restrict sensitive input, require code and license review, and measure defect rates before expanding access.','Limita datos sensibles, exige revisar código y licencias, y mide defectos antes de ampliar el acceso.'], outcome:['The pilot continued under narrower controls, with expansion contingent on evidence.','La prueba continuó con controles más estrictos y su ampliación quedó sujeta a evidencia.'] },
];

const names: Record<Level, [string, string]> = {
  A1:['Jamie (User)','Alex (IT Helper)'], A2:['Taylor (Employee)','Morgan (IT Support)'],
  B1:['Jordan (Engineer)','Casey (Network Support)'], B2:['Riley (Service Owner)','Morgan (Security Analyst)'],
  C1:['Avery (Incident Lead)','Jordan (Principal Engineer)'],
};
const roles: Record<Level, [string,string]> = {
  A1:['customer','technician'], A2:['customer','technician'], B1:['student','technician'],
  B2:['manager','technician'], C1:['manager','technician'],
};
const closings: Record<Level, Pair> = {
  A1:['Good. The device works now. Never share your password.','Bien. El dispositivo funciona. Nunca compartas tu contraseña.'],
  A2:['Thanks for checking. I have added the safe steps to the support note.','Gracias por comprobarlo. Añadí los pasos seguros a la nota de soporte.'],
  B1:['I will document the evidence and escalate it if the issue returns.','Documentaré la evidencia y escalaré el caso si vuelve a ocurrir.'],
  B2:['We will retain the audit trail and review the control after the change.','Conservaremos la auditoría y revisaremos el control después del cambio.'],
  C1:['We will track the owner, service impact, and follow-up evidence in the incident review.','Registraremos responsables, impacto y evidencia de seguimiento en la revisión del incidente.'],
};
const duration: Record<Level, string> = { A1:'2–3 min', A2:'3–4 min', B1:'4–5 min', B2:'5–6 min', C1:'6–8 min' };

function storyText(item: TechnologyCase, index: number): string[] {
  const [problem, check, reply, action, outcome] = [item.problem[0], item.check[0], item.reply[0], item.action[0], item.outcome[0]];
  const learner = names[item.level][0].split(' (')[0];
  const openings: Record<Level, string[]> = {
    A1:[`${learner} visits the IT desk with a device problem.`,`${learner} needs help with a computer in class.`,`${learner} asks the school IT helper for support.`],
    A2:[`${learner} contacts the help desk after a problem interrupted a class task.`,`${learner} reports the issue and explains what happened first.`,`${learner} describes a device problem and the steps already tried.`],
    B1:[`The support team receives a report about a service interruption.`,`${learner} has documented the symptoms before contacting the network team.`,`A recurring technical fault has started affecting the team’s daily work.`],
    B2:[`The service owner raises a controlled change after reviewing the operational risk.`,`An incident has been reported through the organization’s approved channel.`,`The response team is assessing impact before it changes a production control.`],
    C1:[`During the technical review, the team separates confirmed evidence from assumptions.`,`The incident lead frames the issue in terms of service impact, dependencies, and recovery options.`,`A cross-functional review examines the failure without treating a single metric as the whole explanation.`],
  };
  const followups: Record<Level, string[]> = {
    A1:['The helper listens and gives one clear step.','They check the device together and use a safe instruction.','The user follows the instruction and checks the screen again.'],
    A2:['The specialist records the result so the employee can repeat the safe process.','The team checks the result before closing the support request.','The employee confirms the fix and keeps the case number for later.'],
    B1:['The engineer records the time, scope, and result so another team can reproduce the check.','The support team compares the evidence with a known-good service before escalating.','The change is tested outside production before the team applies it broadly.'],
    B2:['The team preserves relevant evidence and communicates only what it has verified.','The owner records the decision, rollback condition, and responsible reviewer.','The response is limited to the affected scope while the team checks for wider impact.'],
    C1:['The team assigns a decision owner, a measurable validation step, and a time for the next review.','The mitigation is evaluated against recovery objectives, user impact, and remaining uncertainty.','The review records trade-offs explicitly so the next team can revisit them with new evidence.'],
  };
  const i = index % 3;
  return [
    `${openings[item.level][i]} ${problem} ${check} ${reply}`,
    `The team recommends the following action: ${action} ${outcome}`,
    `${followups[item.level][i]} ${closings[item.level][0]}`,
  ];
}

const listeningPrompts = [
  'What problem was reported?',
  'What did the support team check?',
  'Which action was taken or recommended?',
  'What was the outcome or next step?',
];

function questionsFor(item: TechnologyCase, levelCases: TechnologyCase[], index: number): ListeningQuestion[] {
  const fields: Array<keyof Pick<TechnologyCase, 'problem'|'check'|'action'|'outcome'>> = ['problem','check','action','outcome'];
  return fields.map((field, questionIndex) => {
    const correct = item[field][0];
    const alternatives = [1,2].map(offset => levelCases[(index + offset) % levelCases.length][field][0]);
    const options = [...alternatives];
    const answer = (index + questionIndex) % 3;
    options.splice(answer, 0, correct);
    return { prompt:listeningPrompts[questionIndex], options, answer };
  });
}

export const technologyListeningStories: ListeningStory[] = technologyCases.map((item, index) => ({
  id:item.id, level:item.level, title:item.title, summary:`Caso de TI: ${item.titleEs}. ${item.outcome[1]}`,
  paragraphs:storyText(item,index),
  questions:questionsFor(item,technologyCases.filter(candidate=>candidate.level===item.level),technologyCases.filter(candidate=>candidate.level===item.level).indexOf(item)),
}));

const dialogueCases = [
  ...technologyCases.filter(item=>item.level==='A1'),
  ...technologyCases.filter(item=>item.level==='A2'),
  ...technologyCases.filter(item=>item.level==='B1').slice(0,8),
  ...technologyCases.filter(item=>item.level==='B2'),
  ...technologyCases.filter(item=>item.level==='C1'),
];

export const technologyDialogues: Dialogue[] = dialogueCases.map((item,index) => {
  const [employee,technician] = names[item.level];
  const [userRole,techRole] = roles[item.level];
  const close = closings[item.level];
  const entries: Array<[0|1,Pair]> = [
    [0,item.problem], [1,['I can help. '+item.check[0],'Puedo ayudarte. '+item.check[1]]],
    [0,item.reply], [1,item.action], [0,item.outcome], [1,close],
  ];
  return {
    id:index+3, title:item.title, titleEs:item.titleEs, level:item.level,
    description:`${item.level} English practice for technical support, IT operations, and workplace communication.`,
    descriptionEs:`Caso de TI: ${item.titleEs}. Practica diagnóstico, instrucciones y comunicación técnica segura.`,
    duration:duration[item.level],
    lines:entries.map(([speaker,pair],lineIndex):DialogueLine=>({
      id:lineIndex+1, speaker:speaker===0?userRole:techRole, speakerName:speaker===0?employee:technician,
      text:pair[0], translation:pair[1],
    })),
  };
});
